class Solution {
    public double minimiseMaxDistance(int[] arr, int k) {
        double low = 0.0;
        double high = 0.0;
        for(int i=1; i<arr.length; i++){
            high = Math.max(high, (arr[i]- arr[i-1]));
        }
        while((high-low) > 1e-6){
            double mid = (high+low)/2.0;
            int cnt = noOfGasStation(arr, mid);
            if(cnt > k){
                low=mid;
            }else{
                high=mid;
            }
        }
        return high;
    }

    int noOfGasStation(int[] arr, double dist){
        int no = 0;
        for(int i=1; i<arr.length; i++){
            int numberInBetween = (int) ((arr[i]-arr[i-1])/dist);
            if((arr[i]-arr[i-1]) == numberInBetween*dist) --numberInBetween;
            no += numberInBetween;
        }
        return no;
    }
}

