## Solution
```javascript[]
class Solution {
  minimiseMaxDistance(arr, k) {
    const ROUND = 10 ** -6;
    const n = arr.length;
    let ans = -1;
    let low = 0,
      high = -1; // Range of minimum distance
    for (let i = 1; i < n; i++) {
      const distance = arr[i] - arr[i - 1];
      if (distance > high) {
        high = distance + ROUND; // Add round becuase you exterme high can be a solution
      }
    }
    while (high - low > 10 ** -6) {
      const mid = (low + high) / 2;
      let totalStations = this.canAccomodate(arr, mid, k, n);
      if (totalStations <= k) {
        // Since if totalStations are less than required, then go left to have more stations since distance decreases
        high = mid;
        ans = mid;
      } else {
        low = mid;
      }
    }

    return ans;
  }

  canAccomodate(arr, maxDistance, k, n) {
    let totalStations = 0;
    for (let i = 1; i < n; i++) {
      let gap = arr[i] - arr[i - 1];
      totalStations = totalStations + Math.floor(gap / maxDistance);
      if (gap % maxDistance === 0) {
        totalStations--;
      }
    }
    return totalStations;
  }
}

