class Solution {
public:

    bool func(vector<int> &arr, long long n, int k, long double mid) {
        long long stations = 0;
        for(int i=1;i<n;++i) {
            long long count = (arr[i] - arr[i-1])/mid;
            stations+=count;
            if(stations>k) return false;
        }

        return true;
    }

    long double minimiseMaxDistance(vector<int> &arr, int k) {
       long long n = arr.size();
       long double low = 0.000000;
       long double high = 0;
       for(int i=1;i<n;++i) {
            high = max((long double)(arr[i]-arr[i-1]),high);
       }
       while(low<=high) {
            long double mid = low + (high-low)/2;
            bool isFeasible = func(arr,n,k,mid);
            if(isFeasible) {
                high = mid - 0.000001;
            }
            else low = mid + 0.000001;
       }
       return low;

    }
};
